export const crmModule: AppModule = { name: 'crm', version: '1.0.0', dependencies: ['core', 'contacts'], routes: [{ id: 'crm-leads', path: '/crm/leads', element: <LeadsPage/> }, { id: 'crm-lead-detail', path: '/crm/leads/:id', element: <LeadDetailPage/> }, { id: 'crm-opportunities', path: '/crm/opportunities', element: <OpportunitiesPage/> }, { id: 'crm-opportunity-detail', path: '/crm/opportunities/:id', element: <OpportunityDetailPage/> }, { id: 'crm-pipeline-settings', path: '/crm/settings/pipelines', element: <PipelineSettingsPage/> }, { id: 'crm-field-designer', path: '/crm/settings/fields', element: <CRMFieldDesignerPageV2/> }], navigation: [{ id: 'crm', label: 'CRM', path: '/crm/leads', order: 350, isGroup: true, icon: BriefcaseBusiness, permissionsAny: [{ scope: 'workspace', name: 'crm.lead.read' }, { scope: 'workspace', name: 'crm.opportunity.read' }] }, { id: 'crm-leads', label: 'Leads', path: '/crm/leads', order: 351, parentId: 'crm', icon: UsersRound, permission: { scope: 'workspace', name: 'crm.lead.read' } }, { id: 'crm-opportunities', label: 'Opportunities', path: '/crm/opportunities', order: 352, parentId: 'crm', icon: CircleDollarSign, permission: { scope: 'workspace', name: 'crm.opportunity.read' } }, { id: 'crm-pipeline-settings', label: 'Sales pipelines', path: '/crm/settings/pipelines', order: 911, parentId: 'settings', icon: Settings2, permissionsAny: [{ scope: 'workspace', name: 'crm.pipeline.manage' }, { scope: 'workspace', name: 'crm.stage.manage' }] }, { id: 'crm-field-designer', label: 'CRM fields', path: '/crm/settings/fields', order: 912, parentId: 'settings', icon: Settings2, permission: { scope: 'workspace', name: 'customization.field.manage' } }] }
